// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address owner, uint256 seedAmt, address attacker, uint256 withdrawAmt) public {
        vm.assume(owner != attacker && owner != address(0) && attacker != address(0) && owner != address(c) && attacker != address(c));
        vm.assume(seedAmt > 0 && withdrawAmt > 0);
        vm.deal(owner, seedAmt);
        vm.prank(owner);
        (bool funded,) = address(c).call{value: seedAmt}("");
        require(funded);
        vm.deal(attacker, 0);
        vm.prank(attacker);
        try c.withdraw() {
            assertTrue(address(c).balance == 0);
        } catch {
            assertTrue(address(c).balance == seedAmt);
        }
    }
}
